Require Import Reals. Require Import Ring. Open Scope R_scope. Lemma test_eq_funs : forall (f g : R -> R) (x : R), (forall t, f t = g t) -> derivable_pt f x -> derivable_pt g x -> (exists l : R, derivable_pt_abs f x l /\ derivable_pt_abs g x l). Proof. intros f g x h_eq hf_dif hg_dif. destruct hf_dif as [l hf_l]. destruct hg_dif as [l' hg_l]. exists l. split. - exact hf_l. - have h_eq_pt : f x = g x. apply h_eq. have h_f_eq_g : forall t, f t = g t. intro t. apply h_eq. have h_deriv_eq : derivable_pt_abs g x l. unfold derivable_pt_abs in *. intro eps. destruct (hf_l eps) as [delta hdelta]. exists delta. intro h neqh hdelta'. have h1 : f (x + h) = g (x + h) by apply h_f_eq_g. have h2 : f x = g x by apply h_f_eq_g. rewrite h1, h2 in hdelta'. exact hdelta'. exact h_deriv_eq. Qed.
